head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnEditPlaceholderChar]<br/>Body Column 정보를 사용하여 특정 Column 의 editPlaceholderChar 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 editPlaceholderChar 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",        
        "Body Column 이 inputType='text', 'calendar' 인 경우에 동작합니다.",
        "editPlaceholderChar(필수) 파라미터로 값이 없는 마스크 문자 위치에 표시할 문자를 설정합니다.",
        "Column 의 inputType='text' 이면 editFormat 속성에 설정된 마스크 문자가 적용됩니다.",
        "Column 의 inputType='calendar' 이면 useEditFormat=true 일때 displayFormat 속성에 설정된 마스크 문자가 적용됩니다.",
        "editPlaceholderChar 속성을 설정하면 정의된 포맷을 미리 표시하고 입력 자리에 속성값에 설정된 문자를 표시합니다.",
        "표시된 입력 자리는 어느 자리에 먼저 설정하든 입력이 가능하지만, 입력값이 확정될때 입력되지 않은 자리는 모두 제거됩니다. (예: '_1_1_' 로 확정 시 '11' 이 최종값)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 columnInfo(0)/editPlaceholderChar(_) 선택
    par_columnInfo.setValue("0");
    par_editPlaceholderChar.setValue("_");
};



// comp 생성 : text(editFormat)/text(editFormat·숨김)/custom(미동작)/calendar(useEditFormat) Column 구성
//  setColumnEditPlaceholderChar 는 inputType='text','calendar' 인 Column 에서만 동작 (custom 은 미동작)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column(숨김 포함) 0:cText(text·editFormat=###-####·동작) / 1:cHide(text·editFormat·숨김) / 2:cCustom(custom·미동작) / 3:cCal(calendar·useEditFormat=true·displayFormat=yyyy-MM-dd·동작), 데이터 3행.\n[절차] columnInfo(인덱스)·editPlaceholderChar(문자) 선택 후 (setColumnEditPlaceholderChar 실행). 반환값과 getColumnEditPlaceholderChar 설정값을 확인. 이후 해당 셀을 더블클릭 편집하면 편집모드 입력창에 마스크+빈자리 문자가 표시되고, 일부만 입력 후 포커스아웃(확정)하면 확정값/표시값이 출력됨.\n[확인] text(0)·calendar(3)만 동작(2:cCustom 미동작·반환 false). 편집모드 빈 자리에 지정 문자 표시. 일부만 입력 후 확정 시 미입력 자리는 제거됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cText" name="cText" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cHide" name="cHide" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cCustom" name="cCustom" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cCal" name="cCal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "cText": "1234567",  "cHide": "010203", "cCustom": "1234567", "cCal": "20250115" },
        { "cText": "9876543",  "cHide": "112233", "cCustom": "9876543", "cCal": "20251231" },
        { "cText": "5550000",  "cHide": "445566", "cCustom": "5550000", "cCal": "20250707" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (text/text(숨김)/custom/calendar Column)
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:660px;height:230px;" editable="true" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnEditPlaceholderChar 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" inputType="text" id="h0" value="0:text(editFormat)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h1" value="1:text(숨김)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h2" value="2:custom(미동작)"></w2:column>';
    strTarget += '<w2:column width="190" inputType="text" id="h3" value="3:calendar(useEditFormat)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    // 0 : text + editFormat -> setColumnEditPlaceholderChar 동작 대상. 빈 마스크 자리에 지정 문자 표시
    strTarget += '<w2:column width="170" inputType="text" dataType="text" editFormat="###-####" id="cText" dataList="cText"></w2:column>';
    // 1 : text + editFormat 숨김(setColumnVisible(1,false)) -> 숨김 Column 포함 인덱스 검증용
    strTarget += '<w2:column width="150" inputType="text" dataType="text" editFormat="##-##-##" id="cHide" dataList="cHide"></w2:column>';
    // 2 : custom -> 전제 미충족(inputType=custom) -> 미동작(setColumnEditPlaceholderChar 반환 false)
    strTarget += '<w2:column width="150" inputType="custom" dataType="text" id="cCustom" dataList="cCustom"></w2:column>';
    // 3 : calendar + useEditFormat=true + displayFormat -> useEditFormat 일때 displayFormat 마스크에 적용
    strTarget += '<w2:column width="190" inputType="calendar" dataType="date" useEditFormat="true" displayFormat="yyyy-MM-dd" id="cCal" dataList="cCal"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(cHide, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// [실행] setColumnEditPlaceholderChar : columnInfo(인덱스) + editPlaceholderChar 문자로 해당 Column 의 editPlaceholderChar 속성을 설정한다.
//  - 쌍이 되는 get 메소드(getColumnEditPlaceholderChar)로 설정값 확인
//  - text/calendar 만 동작. custom 은 반환 false + 미설정(getColumnEditPlaceholderChar 도 false)
scwin.btn_setColumnEditPlaceholderChar_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let phChar = par_editPlaceholderChar.getValue();
    let colID = target1.getColumnID(columnInfo);
    let cellInfo = target1.getCellInfo(columnInfo);
    let inputType = (cellInfo && cellInfo.options) ? cellInfo.options.inputType : '';

    // 인덱스로 호출 (숨김 Column 포함 인덱스, MultiLine 이어도 고유 인덱스)
    let ret = target1.setColumnEditPlaceholderChar(columnInfo, phChar);

    // 쌍이 되는 get 메소드로 설정값 확인 (text/calendar 는 설정값, custom 은 false)
    let getPh = target1.getColumnEditPlaceholderChar(columnInfo);

    let msg = "setColumnEditPlaceholderChar(" + columnInfo + ", '" + phChar + "') [" + colID + ", inputType=" + inputType + "] 반환값=" + ret;
    msg += "\n[getColumnEditPlaceholderChar] " + getPh;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// [이벤트] 셀 편집 진입 시 : 편집모드 입력창에 마스크+빈자리 문자(editPlaceholderChar)가 미리 표시됨을 확인
scwin.target1_onbeforeedit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    // 편집모드 진입 직후 공용 에디터 input 의 표시값(마스크+placeholder) 캡처
    setTimeout(function () {
        let editor = document.querySelector("input[id^='G_'][id$='target1__" + colID + "']");
        if (editor) {
            let msg = "편집모드 진입 [" + colID + "] (" + row + "," + col + ")";
            msg += "\n[입력창 표시(마스크+빈자리 문자)] " + editor.value;
            wf_body_bottom.getObj("scwin").setReturnValue(msg);
        }
    }, 50);
};

// [이벤트] 셀 편집 확정(포커스아웃) 시 : 일부만 입력하고 확정하면 미입력 자리가 제거된 최종값을 확인
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    let cellData = target1.getCellData(row, col);   // 확정 최종값 (미입력 자리 제거됨)
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");
    let dispVal = td ? td.textContent.trim() : '';
    let msg = "편집->확정 [" + colID + "] (" + row + "," + col + ")";
    msg += "\n[확정값(getCellData)] " + cellData;
    msg += "\n[표시값] " + dispVal;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};
